1643	    if (id === 'bill')     return <ChargeBill go={go} selectedTenant={selectedTenant} amount={amount} onEditAmount={() => { setAmountDest('bill'); go('amount'); }} chargeType={chargeType} setChargeType={setChargeType} label={chargeLabel} setLabel={setChargeLabel} dueSel={dueSel} setDueSel={setDueSel} splitOn={splitMode} onToggleSplit={() => setSplitMode(m => !m)} onSend={handleBill} sending={billMutation.isPending} docUrl={chargeDocUrl} docName={chargeDocName} uploadingDoc={uploadingDoc} onUploadDoc={uploadChargeDoc} onClearDoc={clearChargeDoc} />;
1644	    if (id === 'external') return <MarkExternal go={go} selectedTenant={selectedTenant} amount={amount} invoices={invoices} onMark={handleMark} marking={markMutation.isPending} />;
1645	    if (id === 'batch')    return <BatchAndAutoScreen {...batchAutoProps} />;
1646	    if (id === 'success')  return <SentSuccess amount={amount} label={successLabel} go={go} kind={successKind} />;
1647	    return null;
1648	  };
