1659	      <div key={'enter-' + currentId + '-' + contentKey} className={`tp-layer${conveyor ? ' entering ' + conveyorDir : ''}`}>
1660	        {renderScreen(currentId)}
1661	      </div>
1662	
1663	      <div className="tp-overlay">
1664	        <TopBanner msg={banner} />
1665	
1666	        <div className={`tp-pfab${fabVisible ? ' show' : ' hide'}${listExpanded && screen === 'home' ? ' expanded' : ''}`}>
1667	          <FabBtn onClick={() => go('tenants')} />
1668	        </div>
1669	
1670	        {/* Full-width row: split pill pinned far-left, action bar centred in the
1671	            space to its right, send pinned right. They are flex siblings, so they
1672	            can never overlap regardless of how wide the bar gets. */}
1673	        <div
1674	          className={`tp-psubbar${subbarVisible ? ' show' : ' hide'}${isFeatureScreen ? ' feature' : ''}${listExpanded && screen === 'home' ? ' expanded' : ''}`}
1675	          style={isFeatureScreen && !listExpanded ? { transform: `translateY(calc(${boundaryDelta}px - 100% - 20px))` } : undefined}
1676	        >
1677	          <div className={`tp-split-slot${screen === 'tenants' ? ' show' : ''}`}>
1678	            <SplitPill on={splitMode} onToggle={() => setSplitMode(m => !m)} />
1679	          </div>
