.tp-psubbar.show .tp-subbar, .tp-psubbar.show .tp-split-slot, .tp-psubbar.show .tp-send-slot { pointer-events: auto; }
.tp-psubbar.hide { opacity: 0; transform: translateY(67px) scale(0.92); pointer-events: none; }
.tp-psubbar.show { opacity: 1; }
.tp-psubbar.feature { transform: translateY(calc(-100% - 20px)); }
.tp-psubbar.expanded { opacity: 0; transform: translateY(-70vh) scale(0.92); pointer-events: none; transition: opacity 220ms ease, transform 480ms cubic-bezier(0.34,1.56,0.64,1); }
