205	function RequestsHome({ invoices, tenants, outstanding, go, onRowTap, expanded, onToggleExpand, onRemind, remindedIds, remindingId }: any) {
206	  const recent = [...invoices]
207	    .filter((i: any) => i.status !== 'voided')
208	    .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
209	    .slice(0, 12);
210	
211	  return (
212	    <div className="tp-screen">
