214	      <div className="stagger" style={{ background: NAVY, height: '42%', padding: '100px 28px 28px', display: 'flex', flexDirection: 'column', justifyContent: 'flex-start', overflow: 'hidden', transform: expanded ? 'translateY(-100%)' : 'translateY(0)', opacity: expanded ? 0 : 1, transition: 'transform 0.55s cubic-bezier(0.34,1.56,0.64,1), opacity 0.4s ease' }}>
215	        <div className="tp-amount" style={{ fontSize: 82, color: BLUE }}>{fmt(outstanding)}</div>
216	        <div style={{ marginTop: 10, color: BLUE, fontWeight: 500, fontSize: 16 }}>outstanding rent</div>
217	      </div>
218	      {/* Bottom — OFFW */}
219	      <div className="stagger" style={{ position: 'absolute', left: 0, right: 0, bottom: 0, top: expanded ? 0 : '42%', background: OFFW, padding: expanded ? '58px 22px 110px' : '132px 22px 92px', display: 'flex', flexDirection: 'column', overflow: 'hidden', zIndex: 2, transition: 'top 0.55s cubic-bezier(0.34,1.56,0.64,1), padding 0.55s cubic-bezier(0.34,1.56,0.64,1)' }}>
220	        <button
221	          onClick={onToggleExpand}
222	          style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12, width: '100%', background: OFFW, border: 'none', cursor: 'pointer', padding: 0, font: 'inherit', position: 'sticky', top: 0, zIndex: 3 }}
223	        >
224	          <div className="tp-stack-title">rent requests</div>
225	          <span style={{ color: BLUE, display: 'flex', padding: '4px 8px', transform: expanded ? 'rotate(90deg)' : 'rotate(0deg)', transition: 'transform 0.45s cubic-bezier(0.34,1.56,0.64,1)' }}>
226	            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 6 15 12 9 18" /></svg>
227	          </span>
