230	          <div className="tp-stack-card">
231	            {recent.length === 0 ? (
232	              <div className="tp-stack-empty">tap + to send a rent request</div>
233	            ) : recent.map((inv: any) => {
234	              const st = invoiceStatusFor(inv);
235	              const dotCls = st === 'paid' ? 'paid' : (st === 'overdue' || st === 'failed') ? 'declined' : st === 'sent' ? 'payment-sent' : 'awaiting';
