238	                  <div style={{ width: 34, height: 34, borderRadius: 999, background: NAVY, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontSize: 11, fontWeight: 800, color: BLUE, letterSpacing: '0.02em', marginRight: 12 }}>
239	                    {(inv.tenantName || '??').split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase()}
240	                  </div>
241	                  {(() => {
242	                    const isSplit = inv.splitEnabled && inv.splitCount > 1;
243	                    const paid = inv.splitPaidCount || 0;
244	                    const showOwing = isSplit && paid > 0 && st !== 'paid';
245	                    return (
246	                      <>
247	                        <div style={{ flex: 1, minWidth: 0 }}>
248	                          <div className="tp-stack-name" style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{inv.tenantName || '—'}</div>
249	                          <div className="tp-stack-meta">
250	                            <span className={`tp-dot ${dotCls}`} />
