  it("is page 0 at the start", () => {
    expect(pageFromScroll(0, 800, 400)).toBe(0);
  });
  it("is page 1 past the halfway scroll", () => {
    // maxScroll = 800 - 400 = 400; half = 200; scrollLeft 260 -> page 1
    expect(pageFromScroll(260, 800, 400)).toBe(1);
