  });
  it("is page 0 just before halfway", () => {
    expect(pageFromScroll(150, 800, 400)).toBe(0);
  });
  it("never exceeds the last page when there is no overflow", () => {
    expect(pageFromScroll(0, 400, 400)).toBe(0);
  });
});

