import React, { useState, useId } from "react";

/**
 * Themeable confirm button.
 *
 * Idle, it renders as a wireframe: transparent fill, a `color` outline and
 * `color` label. On press it fills solid `color`, the label colour shifts to
 * `onSolidColor` and smoothly morphs into a `onSolidColor` tick that draws
 * itself in.
 *
 * Colours are props so every surface keeps its own palette while sharing the
 * one animation. For the property/terminal theme pass color="#58ABFF"
 * (light blue) and onSolidColor="#040D6D" (navy).
 *
 * State can be uncontrolled (animates on click, the default) or controlled via
 * the `confirmed` prop — useful when the tick should reflect an async result
 * (e.g. confirmed={mutation.isSuccess}) or be reset by the parent.
 */
export type ConfirmButtonProps = {
  children: React.ReactNode;
  onConfirm?: () => void;
  /** Wireframe outline + label colour, and the solid fill once pressed. */
  color?: string;
  /** Label + tick colour once the button is solid. */
  onSolidColor?: string;
  /** Controlled confirmed state. Omit for uncontrolled (animates on click). */
  confirmed?: boolean;
  disabled?: boolean;
  /** Extra classes for sizing/layout (colours are driven by the props above). */
  className?: string;
  style?: React.CSSProperties;
  type?: "button" | "submit";
  "aria-label"?: string;
  "data-testid"?: string;
};

export function ConfirmButton({
  children,
  onConfirm,
  color = "#58ABFF",
  onSolidColor = "#040D6D",
  confirmed,
  disabled = false,
  className,
  style,
  type = "button",
  ...rest
}: ConfirmButtonProps) {
  const [internalConfirmed, setInternalConfirmed] = useState(false);
  const isControlled = confirmed !== undefined;
  const isConfirmed = isControlled ? confirmed! : internalConfirmed;
  const reactId = useId();
  const titleId = `cb-${reactId}`;

  const handleClick = () => {
    if (disabled || isConfirmed) return;
    if (!isControlled) setInternalConfirmed(true);
    onConfirm?.();
  };

  return (
    <button
      type={type}
      onClick={handleClick}
      disabled={disabled}
      className={className}
      style={{
        position: "relative",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        borderRadius: 999,
        border: `1.5px solid ${color}`,
        background: isConfirmed ? color : "transparent",
        color: isConfirmed ? onSolidColor : color,
        fontFamily: "'Outfit', system-ui, sans-serif",
        fontWeight: 600,
        cursor: disabled ? "default" : "pointer",
        opacity: disabled ? 0.5 : 1,
        WebkitTapHighlightColor: "transparent",
        transition:
          "background 0.25s ease, border-color 0.25s ease, color 0.2s ease, transform 0.12s ease",
        ...style,
      }}
      {...rest}
    >
      {/* Label — fades and shrinks out as the button goes solid. Stays in normal
          flow so the button keeps its width while the tick overlays it. */}
      <span
        aria-hidden={isConfirmed}
        style={{
          display: "inline-flex",
          alignItems: "center",
          gap: 6,
          opacity: isConfirmed ? 0 : 1,
          transform: isConfirmed ? "scale(0.82)" : "scale(1)",
          transition: "opacity 0.18s ease, transform 0.22s ease",
        }}
      >
        {children}
      </span>

      {/* Tick — overlays the centre and draws itself in once confirmed. */}
      <span
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: isConfirmed ? 1 : 0,
          transition: "opacity 0.2s ease 0.08s",
          pointerEvents: "none",
        }}
      >
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-labelledby={titleId} role="img">
          <title id={titleId}>confirmed</title>
          <path
            d="M5 13l4 4L19 7"
            stroke={onSolidColor}
            strokeWidth={3}
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            style={{
              strokeDasharray: 1,
              strokeDashoffset: isConfirmed ? 0 : 1,
              transition: "stroke-dashoffset 0.4s cubic-bezier(0.65,0,0.35,1) 0.12s",
            }}
          />
        </svg>
      </span>
    </button>
  );
}

